import semver

def test_parse_uses_fast_path_for_standard_version():
    class TrackingVersion(semver.Version):
        def __new__(cls, *args, **kwargs):
            instance = super().__new__(cls)
            instance._init_via_native = bool(args) and not kwargs
            return instance

        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)

    version = TrackingVersion.parse("1.2.3")
    assert version._init_via_native

