from cachetools import FIFOCache

def test_cache_rejects_negative_size_with_well_formed_message():
    class NegativeSizeCache(FIFOCache):
        def getsizeof(self, value):
            if value == "negative":
                return -1
            return 1

    cache = NegativeSizeCache(maxsize=10)
    try:
        cache["key"] = "negative"
    except ValueError as e:
        message = str(e).lower()
        assert "negative" in message
        assert "size" in message
        assert "_" not in message
    else:
        assert False, "Expected ValueError for negative size"

