"""Test cache attribute accessibility on cachedmethod wrapper."""

from cachetools import cachedmethod


def test_cachedmethod_wrapper_has_cache_attribute():
    """Wrapper should expose the cache dict via .cache attribute."""
    cache = {}

    class Example:
        @cachedmethod(lambda self: cache)
        def compute(self, value):
            return value * 2

    # Access the wrapper directly from the class
    wrapper = Example.compute

    # The wrapper must have a 'cache' attribute pointing to our cache
    assert hasattr(wrapper, "cache")
    assert wrapper.cache == cache

from cachetools import cachedmethod


def test_cached_method_cache_attribute_reflects_actual_cache():
    """The .cache attribute on the decorated method must reference the live cache."""
    cache = {}

    class Example:
        @cachedmethod(lambda _: cache)
        def compute(self, x):
            return x * 2

    # Get the decorated method from the class (public interface)
    decorated = Example.compute

    # The .cache attribute must exist and be the cache dict
    method_cache = getattr(decorated, "cache", None)

    # Assert it is exactly the cache we provided (by content)
    assert method_cache == {}

    # Verify it's the live cache by using it
    obj = Example()
    assert obj.compute(3) == 6
    assert method_cache == {3: 6}

    # Clear via the attribute
    method_cache.clear()
    assert method_cache == {}

    # Next call repopulates
    assert obj.compute(3) == 6
    assert method_cache == {3: 6}

import threading
from cachetools import cachedmethod


def test_cache_lock_attribute_is_provided_lock():
    """cache_lock on the decorated method should be the lock instance passed in."""
    lock = threading.Lock()
    cache_storage = {}

    def cache_factory(_):
        return cache_storage

    class Cached:
        @cachedmethod(cache_factory, lock=lock)
        def method(self, x):
            return x

    assert Cached.method.cache_lock is lock

import threading
from cachetools import cachedmethod


def test_cache_condition_attribute_is_set():
    """Verify that the cache_condition attribute is correctly exposed on the decorated method."""
    cond = threading.Condition()
    cache_dict = {}

    class Example:
        @cachedmethod(lambda self: cache_dict, cond=cond)
        def compute(self, value):
            return value * 2

    # Access the descriptor from the class dict to avoid any descriptor protocol side-effects
    descriptor = Example.__dict__["compute"]

    # The descriptor should have the cache_condition attribute
    assert hasattr(descriptor, "cache_condition")
    assert descriptor.cache_condition == cond
